def calculate(a, operator, b):
    if operator == "+":
        return a + b
    elif operator == "-":
        return a - b
    elif operator == "*":
        return a * b
    elif operator == "/":
        if b == 0:
            raise ValueError("除数不能为 0")
        return a / b
    else:
        raise ValueError("不支持的运算符，请使用 +、-、* 或 /")

print(calculate(10, "+", 5))  # 15
print(calculate(10, "-", 5))  # 5
print(calculate(10, "*", 5))  # 50
print(calculate(10, "/", 5))  # 2.0
```
